    async def fetch_currencies(self, params={}) -> Currencies:
        """
        fetches all available currencies on the exchange

        https://www.wizardswap.io/api

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: an associative dictionary of currencies
        """
        #
        # GET /api/currency returns rich data:
        #  [
        #      {
        #          "symbol": "PART", "name": "Particl", "decimals": 8,
        #          "minamt": "0.00001", "enabled": 1, "maintenance": 0,
        #          "validation_address": "...", "explorer": "https://...",
        #          ...
        #      },
        #      ...
        #  ]
        #
        # GET /api/currencies returns simple array(may be blocked by DDoS-Guard):
        #  ["btc","xmr","eth",...]
        #
        richResponse = await self.publicGetCurrency(params)
        if isinstance(richResponse, list) and len(richResponse) > 0:
            return self.parse_rich_currencies(richResponse)
        # Last resort: use hardcoded list
        defaultIds = self.safe_list(self.options, 'defaultCurrencyIds', [])
        return self.parse_simple_currencies(defaultIds)

    def parse_rich_currencies(self, response):
        result = {}
        for i in range(0, len(response)):
            entry = response[i]
            rawSymbol = self.safe_string(entry, 'symbol')
            if rawSymbol is None:
                continue
            currencyId = rawSymbol.lower()
            code = self.safe_currency_code(currencyId)
            enabled = self.safe_integer(entry, 'enabled', 1)
            maintenance = self.safe_integer(entry, 'maintenance', 0)
            active = (enabled == 1) and (maintenance == 0)
            decimals = self.safe_integer(entry, 'decimals')
            precision = None
            if decimals is not None:
                precision = self.parse_number(self.parse_precision(self.safe_string(entry, 'decimals')))
            minAmt = self.safe_number(entry, 'minamt')
            result[code] = self.safe_currency_structure({
                'id': currencyId,
                'code': code,
                'name': self.safe_string(entry, 'name'),
                'active': active,
                'deposit': active,
                'withdraw': active,
                'fee': None,
                'precision': precision,
                'limits': {
                    'amount': {'min': minAmt, 'max': None},
                    'withdraw': {'min': minAmt, 'max': None},
                },
                'info': entry,
            })
        return result

    def parse_simple_currencies(self, currencyIds):
        result = {}
        for i in range(0, len(currencyIds)):
            currencyId = currencyIds[i]
            code = self.safe_currency_code(currencyId)
            result[code] = self.safe_currency_structure({
                'id': currencyId,
                'code': code,
                'name': None,
                'active': True,
                'deposit': True,
                'withdraw': True,
                'fee': None,
                'precision': None,
                'limits': {
                    'amount': {'min': None, 'max': None},
                    'withdraw': {'min': None, 'max': None},
                },
                'info': currencyId,
            })
        return result

    async def fetch_markets(self, params={}) -> List[Market]:
        """
        retrieves all available swap pairs from /pairs and /currency

        https://www.wizardswap.io/api

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns Market[]: an array of objects representing market data
        """
        currencies = self.safe_dict(self.options, 'cachedCurrencies')
        if not currencies:
            currencies = await self.fetch_currencies(params)
        #
        # GET /api/pairs returns:
        # {
        #     "part": ["pivx","xmr","zec","dash","btc","ltc","eth","firo","zano","bch"],
        #     "xmr":  ["part","pivx","zec","dash","btc","ltc","eth","firo","zano","bch"],
        #     ...
        # }
        #
        pairsData = await self.publicGetPairs(params)
        result = []
        if pairsData is not None and isinstance(pairsData, dict):
            baseIds = list(pairsData.keys())
            for i in range(0, len(baseIds)):
                baseId = baseIds[i]
                baseCode = self.safe_currency_code(baseId)
                quoteIds = self.safe_list(pairsData, baseId, [])
                for j in range(0, len(quoteIds)):
                    quoteId = quoteIds[j]
                    quoteCode = self.safe_currency_code(quoteId)
                    baseCurrency = self.safe_dict(currencies, baseCode, {})
                    quoteCurrency = self.safe_dict(currencies, quoteCode, {})
                    result.append(self.build_market_entry(baseId, quoteId, baseCode, quoteCode, baseCurrency, quoteCurrency))
        else:
            # Fallback: build from currencies(N*(N-1) pairs)
            codes = list(currencies.keys())
            for i in range(0, len(codes)):
                baseCode = codes[i]
                baseCurrency = currencies[baseCode]
                baseId = self.safe_string(baseCurrency, 'id')
                for j in range(0, len(codes)):
                    if i == j:
                        continue
                    quoteCode = codes[j]
                    quoteCurrency = currencies[quoteCode]
                    quoteId = self.safe_string(quoteCurrency, 'id')
                    result.append(self.build_market_entry(baseId, quoteId, baseCode, quoteCode, baseCurrency, quoteCurrency))
        return result

    def build_market_entry(self, baseId, quoteId, baseCode, quoteCode, baseCurrency, quoteCurrency):
        symbol = baseCode + '/' + quoteCode
        baseMinAmt = self.safe_number(self.safe_dict(self.safe_dict(baseCurrency, 'limits', {}), 'amount', {}), 'min')
        return {
            'id': baseId + '_' + quoteId,
            'symbol': symbol,
            'base': baseCode,
            'quote': quoteCode,
            'baseId': baseId,
            'quoteId': quoteId,
            'settle': None,
            'settleId': None,
            'type': 'spot',
            'spot': True,
            'margin': False,
            'swap': False,
            'future': False,
            'option': False,
            'active': True,
            'contract': False,
            'linear': None,
            'inverse': None,
            'contractSize': None,
            'expiry': None,
            'expiryDatetime': None,
            'strike': None,
            'optionType': None,
            'taker': self.parse_number('0.022'),
            'maker': self.parse_number('0.022'),
            'percentage': True,
            'tierBased': False,
            'feeSide': 'get',
            'precision': {
                'amount': self.safe_number(baseCurrency, 'precision'),
                'price': self.safe_number(quoteCurrency, 'precision'),
            },
            'limits': {
                'leverage': {'min': None, 'max': None},
                'amount': {'min': baseMinAmt, 'max': None},
                'price': {'min': None, 'max': None},
                'cost': {'min': None, 'max': None},
            },
            'created': None,
            'info': {
                'baseId': baseId,
                'quoteId': quoteId,
            },
        }

    async def fetch_ticker(self, symbol: str, params={}) -> Ticker:
        """
        fetches a price ticker / estimate for a swap pair

        https://www.wizardswap.io/api

        :param str symbol: unified market symbol, e.g. 'XMR/BTC'
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.amount_from]: amount to estimate, defaults to '1'
        :returns dict: a `ticker structure <https://docs.ccxt.com/?id=ticker-structure>`
        """
        await self.load_markets()
        market = self.market(symbol)
        amountFrom = self.safe_string(params, 'amount_from', '1')
        params = self.omit(params, 'amount_from')
        request = {
            'currency_from': market['baseId'],
            'currency_to': market['quoteId'],
            'amount_from': amountFrom,
        }
        response = await self.publicPostEstimate(self.extend(request, params))
        #
        #  {"estimated_amount": "0.00476907"}
        #
        return self.parse_ticker(response, market)

    def parse_ticker(self, ticker: dict, market: Market = None) -> Ticker:
        currencyFrom = self.safe_string(ticker, 'currency_from')
        currencyTo = self.safe_string(ticker, 'currency_to')
        symbol = self.safe_string(market, 'symbol')
        if currencyFrom is not None and currencyTo is not None:
            baseCode = self.safe_currency_code(currencyFrom)
            quoteCode = self.safe_currency_code(currencyTo)
            symbol = baseCode + '/' + quoteCode
        last = self.safe_string_2(ticker, 'estimated_amount', 'rate')
        return self.safe_ticker({
            'symbol': symbol,
            'timestamp': None,
            'datetime': None,
            'high': None,
            'low': None,
            'bid': last,
            'bidVolume': None,
            'ask': last,
            'askVolume': None,
            'vwap': None,
            'open': None,
            'close': last,
            'last': last,
            'previousClose': None,
            'change': None,
            'percentage': None,
            'average': None,
            'baseVolume': None,
            'quoteVolume': None,
            'info': ticker,
        }, market)

    async def create_order(self, symbol: str, type: OrderType, side: OrderSide, amount: float, price: Num = None, params={}) -> Order:
        """
        create a swap order on WizardSwap(no API key needed)

        https://www.wizardswap.io/api

        :param str symbol: unified market symbol, e.g. 'XMR/BTC'
        :param str type: order type – only 'market' is supported(floating rate)
        :param str side: 'buy' or 'sell' – for swaps self is always 'sell'(sell base for quote)
        :param float amount: amount of the base currency to send
        :param float [price]: not used for WizardSwap
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str params['address_to']: destination address for the quote currency
        :param str [params.refund_address]: refund address for the base currency
        :returns dict: an `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        await self.load_markets()
        market = self.market(symbol)
        addressTo = self.safe_string(params, 'address_to')
        if addressTo is None:
            raise ArgumentsRequired(self.id + ' createOrder() requires params.address_to – the destination address for the received currency')
        request = {
            'currency_from': market['baseId'],
            'currency_to': market['quoteId'],
            'amount_from': self.number_to_string(amount),
            'address_to': addressTo,
        }
        refundAddress = self.safe_string(params, 'refund_address')
        if refundAddress is not None:
            request['refund_address'] = refundAddress
        params = self.omit(params, ['address_to', 'refund_address'])
        response = await self.publicPostExchange(self.extend(request, params))
        if ((isinstance(response, bool)) and not response) or response == 'False':
            raise InvalidOrder(self.id + ' createOrder() failed: exchange returned False(order rejected)')
        #
        #  {
        #      "id": "08A75WA1",
        #      "type": "fixed",
        #      "timestamp": "2026-03-24 21:48:22",
        #      "updated_at": "2026-03-24 22:48:21",
        #      "currency_from": "xmr",
        #      "amount_from": "0.1000...",
        #      "expected_amount": "0.1000...",
        #      "amount_to": "0.000467720...",
        #      "address_from": "88hsysd...",
        #      "address_to": "1Bitcoin...",
        #      "extra_id_from": "",
        #      "extra_id_to": "",
        #      "tx_from": "",
        #      "tx_to": "",
        #      "status": "waiting",
        #      "refund_address": null,
        #      "refund_extra_id": "",
        #      "currencies": {...}
        #  }
        #
        # Note: create response may omit currency_to; pass market to parseOrder.
        return self.parse_order(response, market)

    async def fetch_order(self, id: str, symbol: Str = None, params={}) -> Order:
        """
        fetch the status of a WizardSwap exchange/swap order

        https://www.wizardswap.io/api

        :param str id: the order / exchange id
        :param str [symbol]: unified market symbol(optional)
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: an `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        request = {
            'id': id,
        }
        response = None
        try:
            response = await self.publicGetExchangeId(self.extend(request, params))
        except Exception as e:
            raise OrderNotFound(self.id + ' order ' + id + ' not found')
        #
        #  {
        #      "id": "08A75WA1",
        #      "timestamp": "2026-03-24 21:48:22",
        #      "updated_at": "2026-03-24 22:48:22",
        #      "currency_from": "xmr",
        #      "currency_to": "btc",
        #      "amount_from": "0.1000...",
        #      "amount_to": "0.000467720...",
        #      "expected_amount": "0.1000...",
        #      "address_from": "88hsysd...",
        #      "address_to": "1Bitcoin...",
        #      "extra_id_from": "",
        #      "extra_id_to": "",
        #      "tx_from": "",
        #      "tx_to": "",
        #      "status": "waiting",
        #      "refund_address": null,
        #      "refund_extra_id": "",
        #      "currencies": [{"symbol": "xmr", ...}, {"symbol": "btc", ...}]
        #  }
        #
        if response is None or not isinstance(response, dict):
            raise OrderNotFound(self.id + ' order ' + id + ' not found')
        # The API returns a dict with status=null for nonexistent orders
        responseStatus = self.safe_string(response, 'status')
        if responseStatus is None:
            raise OrderNotFound(self.id + ' order ' + id + ' not found')
        return self.parse_order(response)

    def parse_order(self, order: dict, market: Market = None) -> Order:
        id = self.safe_string(order, 'id')
        currencyFrom = self.safe_string(order, 'currency_from')
        currencyTo = self.safe_string(order, 'currency_to')
        parsedSymbol = None
        if currencyFrom is not None and currencyTo is not None:
            baseCode = self.safe_currency_code(currencyFrom)
            quoteCode = self.safe_currency_code(currencyTo)
            parsedSymbol = baseCode + '/' + quoteCode
        # Prefer parsed symbol from response, fall back to market
        symbol = parsedSymbol
        if symbol is None:
            symbol = self.safe_string(market, 'symbol')
        rawStatus = self.safe_string(order, 'status')
        status = self.parse_order_status(rawStatus)
        amountFrom = self.safe_string_2(order, 'expected_amount', 'amount_from')
        amountTo = self.safe_string(order, 'amount_to')
        # Parse timestamp from "2026-03-24 21:48:22" format
        timestampStr = self.safe_string(order, 'timestamp')
        timestamp = None
        if timestampStr is not None:
            timestamp = self.parse8601(timestampStr.replace(' ', 'T') + 'Z')
        updatedAtStr = self.safe_string(order, 'updated_at')
        lastUpdateTimestamp = None
        if updatedAtStr is not None:
            lastUpdateTimestamp = self.parse8601(updatedAtStr.replace(' ', 'T') + 'Z')
        return self.safe_order({
            'id': id,
            'clientOrderId': None,
            'info': order,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'lastTradeTimestamp': None,
            'lastUpdateTimestamp': lastUpdateTimestamp,
            'symbol': symbol,
            'type': 'market',
            'timeInForce': None,
            'postOnly': None,
            'side': 'sell',
            'price': amountTo,       # estimated receive amount
            'stopPrice': None,
            'triggerPrice': None,
            'amount': amountFrom,     # amount sent
            'cost': None,
            'average': None,
            'filled': None,
            'remaining': None,
            'status': status,
            'fee': {
                'currency': None,
                'cost': None,
                'rate': self.parse_number('0.022'),
            },
            'trades': None,
        }, market)

    def parse_order_status(self, status: Str) -> Str:
        statuses = self.safe_dict(self.options, 'statusMapping', {})
        return self.safe_string(statuses, status, status)

    def sign(self, path, api='public', method='GET', params={}, headers=None, body=None):
        useOnion = self.safe_bool(self.options, 'useOnion', False)
        baseUrl = self.urls['api']['rest']
        if useOnion:
            baseUrl = self.safe_string(self.options, 'onionUrl', baseUrl)
        url = baseUrl + '/' + self.implode_params(path, params)
        query = self.omit(params, self.extract_params(path))
        if method == 'GET':
            if query:
                url += '?' + self.urlencode(query)
        elif method == 'POST':
            if query:
                body = self.json(query)
                headers = {
                    'Content-Type': 'application/json',
                }
        return {'url': url, 'method': method, 'body': body, 'headers': headers}

    def handle_errors(self, httpCode: int, reason: str, url: str, method: str, headers: dict, body: str, response, requestHeaders, requestBody):
        if response is None:
            return None
        #
        # error responses from WizardSwap:
        #  {"error": "some error message"}
        #
        error = self.safe_string(response, 'error')
        if error is not None:
            raise ExchangeError(self.id + ' ' + error)
        message = self.safe_string(response, 'message')
        if message is not None and httpCode >= 400:
            raise BadRequest(self.id + ' ' + message)
        return None
